  "signal_basis": {
    "component_id": "C020.signal_basis",
    "value": "Reviewing evidence for and against competing explanations leaves them undistinguished; observed behavior may fit several explanations.",
    "scope": "The mapping's non-discriminating-evidence branch after evidence review.",
