      "rationale": "These spans supply the evidence-review operation, its non-discriminating branch, and the possibility that behavior fits multiple explanations."
    }
  },
  "stated_empirical_relation": {
    "component_id": "C020.stated_empirical_relation",
    "value": "NOT_APPLICABLE",
    "scope": "NOT_APPLICABLE",
    "provenance": {
